    public function find(string $slug): ?array
    {
        foreach ($this->all() as $recipe) if ($recipe['slug'] === $slug) return $recipe;
        return null;
    }

    private function r(string $slug, string $title, string $category, string $description, string $work, string $total, string $yield, bool $quick, bool $onePan, string $equipment, array $ingredients, array $steps, array $tips, array $allergens): array
    {
        $vegetarian = ! in_array($slug, ['kremet-pasta-med-skinke-og-erter', 'polsegryte-med-tomat-og-bonner', 'fiskekaker-i-wrap'], true);

        return compact('slug', 'title', 'category', 'description', 'work', 'total', 'yield', 'quick', 'onePan', 'vegetarian', 'equipment', 'ingredients', 'steps', 'tips', 'allergens');
    }
